package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.json.JsonMapper;import com.ruoyi.medical.contracts.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.io.*;import java.util.*;
/** Explicit deployment input of existing approved reference identities. Does not load secret values. */
public final class ConfiguredCredentialDirectory implements ApprovedCredentialAuthority.Directory {
 private final Path file;private final JsonMapper json=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public ConfiguredCredentialDirectory(Path approvedReferenceFile){if(approvedReferenceFile==null||!approvedReferenceFile.isAbsolute())throw new IllegalArgumentException("An absolute approved reference manifest is required");file=approvedReferenceFile.normalize();}
 @Override public List<ApprovedCredentialAuthority.Binding> current(String tenant,String reference){try{
  if(!file.getParent().toRealPath().equals(file.getParent())||Files.isSymbolicLink(file))deny();var owner=Files.getOwner(Path.of(System.getProperty("user.home")));var parent=Files.readAttributes(file.getParent(),PosixFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!parent.isDirectory()||!parent.owner().equals(owner)||!parent.permissions().equals(Set.of(PosixFilePermission.OWNER_READ,PosixFilePermission.OWNER_WRITE,PosixFilePermission.OWNER_EXECUTE)))deny();var attrs=Files.readAttributes(file,PosixFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!attrs.isRegularFile()||attrs.size()>65536||!attrs.permissions().equals(Set.of(PosixFilePermission.OWNER_READ,PosixFilePermission.OWNER_WRITE)))deny();
  if(!attrs.owner().equals(owner)||((Number)Files.getAttribute(file,"unix:nlink",LinkOption.NOFOLLOW_LINKS)).longValue()!=1)deny();byte[] bytes;try(var stream=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){bytes=stream.readNBytes(65537);}if(bytes.length>65536)deny();var root=json.readTree(bytes);if(root==null||!root.isArray()||root.size()>1000)deny();var results=new ArrayList<ApprovedCredentialAuthority.Binding>();var keys=new HashSet<String>();
  for(var n:root){var fields=new HashSet<String>();n.fieldNames().forEachRemaining(fields::add);if(!fields.equals(Set.of("tenant_id","reference_id","revision","provider","endpoint","approval_version","approval_sha256","active")))deny();for(String key:List.of("tenant_id","reference_id","approval_version"))WireValues.uuid(n.required(key).textValue());WireValues.hash(n.required("approval_sha256").textValue());if(!n.required("active").isBoolean()||!n.required("revision").isTextual()||!n.required("revision").textValue().matches("[!-~]{1,128}")||!n.required("provider").isTextual()||!n.required("endpoint").isTextual())deny();String id=n.required("tenant_id").asText()+":"+n.required("reference_id").asText();if(!keys.add(id))deny();if(tenant.equals(n.required("tenant_id").asText())&&reference.equals(n.required("reference_id").asText()))results.add(new ApprovedCredentialAuthority.Binding(tenant,reference,n.required("revision").asText(),n.required("provider").asText(),n.required("endpoint").asText(),n.required("approval_version").asText(),n.required("approval_sha256").asText(),n.required("active").booleanValue()));}
  var after=Files.readAttributes(file,PosixFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!attrs.owner().equals(after.owner())||!attrs.permissions().equals(after.permissions())||!Objects.equals(attrs.fileKey(),after.fileKey())||attrs.size()!=after.size()||!attrs.lastModifiedTime().equals(after.lastModifiedTime()))deny();return List.copyOf(results);
 }catch(IOException e){throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);}}
 private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
